import React, { useState } from 'react';
import Product from './Product';
import Result from './Result';

export default function Close() {
  const [flag, setFlag] = useState(false); // false = hidden

  function handleShow() {
    setFlag(true); // show product
  }

  function handleOff() {
    setFlag(false); // hide product
  }

  return (
    <>
      <div className="text-center mt-4">
        <button onClick={handleShow} className="btn btn-success me-2">
          Show
        </button>
        <button onClick={handleOff} className="btn btn-danger">
          Off
        </button>
        <Result flag={flag} />
      </div>

      {flag && <Product />}
    </>
  );
}
